	// HYPOTHESIS-1: Adaptive prefix weight by input length improves cache_warmup without hurting load_spikes by removing harmful overload penalties
	// MECHANISM-1: Short inputs get load-balanced (no cache benefit), long inputs get cache-affine; removing overload penalty avoids oscillation in load_spikes
	// EXPECT-1: avg_e2e_ms < 2900

	// HYPOTHESIS-2: Realtime SLO requests routed by load-balance avoid queuing delays in load_spikes where dominant prefix creates hot spots
	// MECHANISM-2: Realtime requests bypass prefix-affinity entirely, getting routed to least-loaded instance; this reduces p95 tail latency
	// EXPECT-2: avg_p95_ms < 5800

	// HYPOTHESIS-3: Using min-load bonus instead of overload penalty provides stable load-awareness without score oscillation
	// MECHANISM-3: Adding a bonus for instances below minimum load threshold gently encourages spreading without the instability of multiplicative penalties
	// EXPECT-3: load_spikes_e2e_ms < 3200

	inputLen := len(req.InputTokens)

	// Compute adaptive weights: [0]=prefix-affinity, [1]=load-balance
	w0 := ws.weights[0] // prefix-affinity weight
	w1 := ws.weights[1] // load-balance weight
	if len(ws.weights) >= 2 {
		if inputLen <= 32 {
			w0 = 0.08
			w1 = 0.92
		} else if inputLen <= 128 {
			// Linear interpolation from 0.08 to 0.55
			t := float64(inputLen-32) / 96.0
			w0 = 0.08 + t*0.47
			w1 = 1.0 - w0
		} else {
			// Long prefix: strong cache affinity
			w0 = 0.65
			w1 = 0.35
		}

		// SLO adjustment
		if req.SLOClass == "realtime" {
			// Realtime: heavily favor load-balance to minimize queuing
			w0 *= 0.3
			w1 = 1.0 - w0
		}
	}

	// Compute composite scores with adaptive weights
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		w := w1
		if i == 0 {
			w = w0
		}
		if i >= 2 {
			w = ws.weights[i]
		}
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * w
		}
	}

	// Gentle load-aware adjustment: find min load, give bonus to lightly-loaded instances
	minLoad := snapshots[0].EffectiveLoad()
	for _, snap := range snapshots {
		if snap.EffectiveLoad() < minLoad {
			minLoad = snap.EffectiveLoad()
		}
	}
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
